-- ========================================
-- SEED DES PERMISSIONS SYSTÈME RBAC (POSTGRESQL)
-- Nettoyage + normalisation complète (4 rôles cibles)
-- ========================================

CREATE TEMP TABLE desired_permissions (
  code VARCHAR(255) PRIMARY KEY,
  label JSONB,
  "group" VARCHAR(255),
  description JSONB
);

ON CONFLICT (code) DO NOTHING;

-- Nettoyage des autorisations liées à des permissions supprimées
DELETE FROM authorizations
WHERE permission_id IN (
  SELECT id FROM permissions WHERE code NOT IN (SELECT code FROM desired_permissions)
);

-- Suppression des permissions obsolètes
DELETE FROM permissions
WHERE code NOT IN (SELECT code FROM desired_permissions);

-- Insertion / mise à jour des permissions normalisées
SELECT code, label, "group", description, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM desired_permissions
ON CONFLICT (code) DO UPDATE SET
  label = EXCLUDED.label,
  "group" = EXCLUDED."group",
  description = EXCLUDED.description,
  deleted_at = NULL,
  updated_at = CURRENT_TIMESTAMP;

DROP TABLE desired_permissions;

DO $$
BEGIN
  RAISE NOTICE '✅ Permissions normalisées: % permissions actives', (SELECT COUNT(*) FROM permissions WHERE deleted_at IS NULL);
END $$;
